!function(){"use strict";app.factory("transferenciaBodegaService",(function($injector){let mS=$injector.get("mainService"),fS=$injector.get("formulario"),url="Inventario/TransferenciaBodega/";return{getDataFilter:getDataFilter,getDataForm:getDataForm,generateSerieComprobante:generateSerieComprobante,getAll:getAll,mapTo:mapTo,insert:insert,update:update,anular:anular,getId:getId,getIdDetalle:getIdDetalle};function getDataFilter(){return mS.getData("get",`${url}?json=${JSON.stringify({tipo:2})}`,null,!0).then(response=>{const data={estabs:[]};if(null!==response&&"object"==typeof response){let dataToGroup={estabs:response.establecimientos};data.estabs=fS.groupingEstab(dataToGroup)}return data})}function getDataForm(){return mS.getData("get",`${url}?json=${JSON.stringify({tipo:3})}`,null,!0).then(response=>{const data={estabs:[],tiposTransaccion:[],tipoDocumento:[]};if(null!==response&&"object"==typeof response){const{ptoEmision:ptoEmision,bodega:bodega,tipoTransaccion:tipoTransaccion,tipoDocumento:tipoDocumento}=response,dataToGroup={estabs:ptoEmision,bodegas:bodega,isGroupBodega:!0};data.estabs=fS.groupingEstab(dataToGroup),data.tiposTransaccion=tipoTransaccion,data.tipoDocumento=tipoDocumento}return data})}function generateSerieComprobante(query){return mS.getData("get",url+"?json="+JSON.stringify(Object.assign(query,{tipo:4})),null,!0).then(response=>{let value=null;if(null!==response&&"object"==typeof response){const{serieComprobante:serieComprobante}=response;value=serieComprobante[0].serieComprobante}return value})}function getAll(obj){let json=JSON.stringify({...obj,tipo:1});return mS.getData("get",`${url}?json=${json}`,null,!0).then(response=>{let transferenciasBodega=[];if(null!==response&&"object"==typeof response){const tempData=response.tranferencias;transferenciasBodega=tempData.map(item=>({idTransferenciaBodega:item.idTransferenciaBodega,idTipoDocumento:item.idTipoDocumento,codEstab:item.codEstab,nroDoc:item.nroDoc,fechaEmision:item.fechaEmision,estadoDesc:item.estadoDesc,estadoCodigo:item.estadoCodigo,total:item.total,bodegaOrigen:item.bodegaOrigen,bodegaDestino:item.bodegaDestino,rowColor:item.rowColor,totalRecords:item.totalRecords}))}return transferenciasBodega})}function mapTo(obj){const{data:data,detalles:detalles,tiposTransaccion:tiposTransaccion,tipoDocumento:tipoDocumento,itemsDeleted:itemsDeleted}=obj,idTipoTransaccionOrigen=tiposTransaccion.find(item=>"S"===item.codigo).idTipoTransaccion,idTipoTransaccionDestino=tiposTransaccion.find(item=>"E"===item.codigo).idTipoTransaccion,idTipoDocumento=tipoDocumento.find(item=>"TB"===item.codigo).idTipoDocumento;data.total=detalles.reduce((acc,curr)=>acc+curr.total,0);const comprobante=mapComprobanteTo(data),resultsDetalleOrigen=mapDetalleOrigen(detalles,idTipoTransaccionOrigen,idTipoDocumento,data.idBodegaOrigen),resultsDetalleDestino=mapDetalleDestino(detalles,idTipoTransaccionDestino,idTipoDocumento,data.idBodegaDestino),mergeDetalle=[...resultsDetalleOrigen,...resultsDetalleDestino].map((item,index)=>({...item,orderIndex:index+1})),tempItemsDeleted=itemsDeleted.map((item,index)=>({...item,orderIndex:index+1})),mergeDetalleOrigen=[...resultsDetalleOrigen,...tempItemsDeleted];return{comprobante:comprobante,detalles:mergeDetalleOrigen,transaccion:[{idTipoTransaccion:idTipoTransaccionOrigen,idTipoDocumento:idTipoDocumento,fechaEmision:comprobante.fechaEmision},{idTipoTransaccion:idTipoTransaccionDestino,idTipoDocumento:idTipoDocumento,fechaEmision:comprobante.fechaEmision}],transaccionDetalle:mergeDetalle}}function mapComprobanteTo(data){return{idPuntoEmision:data.idPuntoEmision,idBodegaOrigen:data.idBodegaOrigen,idBodegaDestino:data.idBodegaDestino,fechaEmision:fS.formatDateMoment(data.fechaEmision),observacion:data.observacion,total:data.total}}function mapDetalleOrigen(detalles,idTipoTransaccionOrigen,idTipoDocumento,idBodega){let results;return detalles.map((item,index)=>({orderIndex:index+1,idTransferenciaBodegaDetalle:item.idTransferenciaBodegaDetalle,idTipoTransaccion:idTipoTransaccionOrigen,idTipoDocumento:idTipoDocumento,idArticulo:item.idArticulo,idBodega:idBodega,idMedida:item.idMedida,descripcion:item.descripcion,cantidad:item.cantidad,conversion:item.conversion,cantidadTransaccion:fS.roundNumber(item.cantidad*item.conversion),precioUnitario:item.precioCosto,precioCosto:item.precioCosto,precioCostoFraccionado:item.precioCostoFraccionado,total:item.total,estado:item.estado}))}function mapDetalleDestino(detalles,idTipoTransaccionDestino,idTipoDocumento,idBodega){let results;return detalles.map((item,index)=>({orderIndex:index+1,idTransferenciaBodegaDetalle:item.idTransferenciaBodegaDetalle,idTipoTransaccion:idTipoTransaccionDestino,idTipoDocumento:idTipoDocumento,idArticulo:item.idArticulo,idBodega:idBodega,idMedida:item.idMedida,cantidad:item.cantidad,conversion:item.conversion,cantidadTransaccion:fS.roundNumber(item.cantidad*item.conversion),precioUnitario:item.precioCosto,precioCosto:item.precioCosto,precioCostoFraccionado:item.precioCostoFraccionado,total:item.total,descripcion:item.descripcion,estado:item.estado}))}function insert(data){return mS.getData("post",`${url}`,{data:data},!0)}function update(id,data){return mS.getData("put",`${url}${id}`,{data:data},!0)}function anular(id){return mS.getData("delete",`${url}${id}`,null,!0)}function getId(id){return mS.getData("get",`${url}GetId/${id}`,null,!0).then(response=>{const data={comprobante:{},detalles:[]};if(null!==response&&"object"==typeof response){const{detalles:detallesTemp}=response,comprobante=response.comprobante[0];data.comprobante={...comprobante,fechaEmision:fS.formatDate(comprobante.fechaEmision),fechaEmisionDocCreado:fS.formatDate(comprobante.fechaEmision)},data.detalles=detallesTemp.map(item=>{const{fraccionado:fraccionado,principal:principal,...restItem}=item,medidas=fS.processAndSortMeasures(principal,fraccionado),dataMedida=medidas.find(m=>m.idMedida===restItem.idMedida);return restItem.conversion=dataMedida.conversion,restItem.medidas=medidas,restItem})}return data})}function getIdDetalle(id){return mS.getData("get",url+"?json="+JSON.stringify(Object.assign({id:id},{tipo:5})),null,!0).then(response=>{const data={dataDocumento:{},detalleDocumento:[]};if(null!==response&&"object"==typeof response){const{detalles:detalles}=response,comprobante=response.comprobante[0];data.dataDocumento={...comprobante,fechaEmision:fS.formatDate(comprobante.fechaEmision)},data.detalleDocumento=detalles}return data})}}))}(window.angular);